document.addEventListener("DOMContentLoaded",()=>{const e=document.querySelectorAll("h1, h2:not(.outil-title)");if(!("IntersectionObserver"in window)){e.forEach(o=>o.classList.add("visible"));return}const n={threshold:.01,rootMargin:"0px 0px -20% 0px"},s=new IntersectionObserver((o,l)=>{o.forEach((t,i)=>{t.isIntersecting&&(t.target.classList.add("visible"),l.unobserve(t.target))})},n);e.forEach(o=>s.observe(o))});console.log("👋 Hello dev ! Tu regardes sous le capot ? Bienvenue dans l’atelier.");window.addEventListener("scroll",function(){const e=document.getElementById("backToTop");window.scrollY>300?e.style.display="block":e.style.display="none"});document.getElementById("backToTop").addEventListener("click",function(){window.scrollTo({top:0,behavior:"smooth"})});console.log("👋 Hello dev ! Tu regardes sous le capot ? Bienvenue dans l’atelier.");
